<script setup>
import {displayLabel,fieldHelp,recordValue} from '../field-help.js'
defineProps(['field','modelValue','model'])
const emit=defineEmits(['update:modelValue'])
</script>
<template><label class="oc-draft-field">{{displayLabel(field)}}<span v-if="!field.optional"> *</span><select v-if="field.template==='cbi/lvalue'" :value="modelValue" @change="emit('update:modelValue',$event.target.value)"><option v-if="field.optional" value="">保持默认</option><option v-for="c in field.choices" :value="c.value">{{recordValue(field,c.label)}}</option></select><input v-else-if="field.template==='cbi/fvalue'" type="checkbox" :checked="String(modelValue)===String(field.enabled)" @change="emit('update:modelValue',$event.target.checked?field.enabled:field.disabled)"><textarea v-else-if="field.template==='cbi/tvalue'" :value="modelValue" @input="emit('update:modelValue',$event.target.value)" rows="3"></textarea><textarea v-else-if="field.template==='cbi/dynlist'" :value="Array.isArray(modelValue)?modelValue.join('\n'):modelValue" @input="emit('update:modelValue',$event.target.value.split('\n').filter(Boolean))" rows="3"></textarea><input v-else :value="modelValue" @input="emit('update:modelValue',$event.target.value)" :type="field.password?'password':'text'" :placeholder="field.placeholder" autocomplete="off"><small v-if="field.template!=='cbi/fvalue'">{{fieldHelp(field,model).format}}</small></label></template>
